message:
Running command: fuser -k 6060/tcp 2>/dev/null || true; python3 - << 'PY' > /outputs/server_6060.log 2>&1 &
import http.server, socketserver, os
class Handler(http.server.SimpleHTTPRequestHandler):
    def do_GET(self):
        if self.path in ('/', '/index.html'):
            self.path = '/candidate_dashboard.html'
        return http.server.SimpleHTTPRequestHandler.do_GET(self)

os.chdir('/workspace')
with socketserver.TCPServer(('0.0.0.0', 6060), Handler) as httpd:
    print('Serving candidate_dashboard.html at http://localhost:6060')
    httpd.serve_forever()
PY
sleep 0.5; ps aux | grep -v grep | grep -E "python3 - << 'PY'|serve_forever|TCPServer|server_6060" || true; echo '---'; curl -sI http://localhost:6060/ | sed -n '1,5p'; echo '---'; curl -sI http://localhost:6060/styles.css | sed -n '1,5p'

